function artReferenceFromData(image,title,id=crypto.randomUUID(),type='uploaded'){const match=typeof image==='string'&&image.match(/^data:(image\/(?:jpeg|png|webp|gif));base64,([A-Za-z0-9+/=]+)$/);if(!match)return null;return{id,title,mimeType:match[1],data:match[2],image,type};}
function projectArtContext(p){const confirmed=chapters.map((chapter,index)=>{if(index===0)return p.idea?.status==='resolved'?`Idea: ${p.idea.confirmedVersion||p.idea.workingIdea||''}`:'';return p.resolved?.[index]?`${chapter.name}: ${p.answers?.[index]?.text||''}`:'';}).filter(Boolean).slice(0,4);return[`Project: ${p.name}`,`Summary: ${projectDescription(p)}`,...confirmed].filter(Boolean).join('\n\n').slice(0,1800);}
function artReferenceRecords(){return artReferences.map(({id,title,type,image})=>({id,title,type,sourceUrl:image}));}
function renderArtReferences(p){const valid=artReferences.map(reference=>`<span class="art-reference-chip"><img src="${esc(reference.image)}" alt=""><span>${esc(reference.title)}</span><button type="button" data-remove-art-reference="${esc(reference.id)}" aria-label="Remove ${esc(reference.title)}">×</button></span>`);const failed=failedArtReferences.map(reference=>`<span class="art-reference-chip is-invalid"><span>${esc(reference.title)} — ${esc(reference.error)}</span><button type="button" data-remove-failed-reference="${esc(reference.id)}" aria-label="Remove failed reference ${esc(reference.title)}">×</button></span>`);$('artReferenceChips').innerHTML=[...valid,...failed].join('');$('artReferenceCount').textContent=artReferences.length?`${artReferences.length} reference${artReferences.length===1?'':'s'}${failed.length?` · ${failed.length} issue${failed.length===1?'':'s'}`:''}`:failed.length?`${failed.length} reference issue${failed.length===1?'':'s'}`:'Optional';const candidates=(p.contexts||[]).filter(item=>typeof item.image==='string'&&item.image.startsWith('data:image/'));$('projectImageReferences').innerHTML=candidates.map(item=>`<button type="button" class="art-reference-choice" data-project-image-reference="${esc(item.id)}" aria-label="Use ${esc(item.title||item.fileName||'project image')} as a reference"><img src="${esc(item.image)}" alt=""><span>${esc(item.title||item.fileName||'Project image')}</span></button>`).join('');$('projectImageReferences').hidden=!candidates.length;$('artReferenceChips').querySelectorAll('[data-remove-art-reference]').forEach(button=>button.onclick=()=>{artReferences=artReferences.filter(reference=>reference.id!==button.dataset.removeArtReference);renderArtReferences(p);syncArtReferenceDraft();});$('artReferenceChips').querySelectorAll('[data-remove-failed-reference]').forEach(button=>button.onclick=()=>{failedArtReferences=failedArtReferences.filter(reference=>reference.id!==button.dataset.removeFailedReference);renderArtReferences(p);$('artStatus').textContent='';});$('projectImageReferences').querySelectorAll('[data-project-image-reference]').forEach(button=>button.onclick=()=>{const image=candidates.find(item=>item.id===button.dataset.projectImageReference);const reference=image&&artReferenceFromData(image.image,image.title||image.fileName||'Project image',image.id,'project');if(reference)addArtReference(reference);});}
function artDraftChanged(){const project=projects.find(p=>p.id===artProjectId);return !!artDraft&&(JSON.stringify({...artDraft,updatedAt:null})!==JSON.stringify({...artOriginal,updatedAt:null})||$('artProjectTitle').value.trim()!==project?.name);}
function syncArtPreview(label){if(!artDraft)return;const image=$('artPreview'),crop=artDraft.crop;image.dataset.cropX=String(crop.x);image.dataset.cropY=String(crop.y);image.dataset.cropZoom=String(crop.zoom);image.onload=()=>applyFloppyArtCrop(image,crop);if(image.src!==new URL(artDraft.sourceUrl,location.href).href)image.src=artDraft.sourceUrl;if(image.complete)applyFloppyArtCrop(image,crop);$('artPreviewHeading').textContent=label;$('artCropZoom').value=String(crop.zoom);$('artCropZoomValue').value=`${Math.round(crop.zoom*100)}%`;artResultReady=artDraftChanged();$('saveProjectArt').disabled=!artResultReady||artEditorState==='generating';$('generateProjectArt').textContent=artResultReady?'Generate another':'Generate art';if(artEditorState!=='generating'){artEditorState=artResultReady?'candidate-ready':'editing';$('artDialog').dataset.state=artEditorState;}}
function syncArtReferenceDraft(){if(!artDraft)return;artDraft=makeProjectArt({...artDraft,references:artReferenceRecords()});syncArtPreview(artDraft.sourceUrl!==artOriginal?.sourceUrl?'Artwork candidate':'Current image');}
function setArtPreview(candidate,label,status){artDraft=makeProjectArt({...candidate,references:artReferenceRecords()});syncArtPreview(label);$('artStatus').textContent=status||'';}
function updateArtCrop(crop,status='Crop ready. Choose “Use image” to apply it.'){if(!artDraft)return;artDraft=makeProjectArt({...artDraft,crop});syncArtPreview(artDraft.sourceUrl!==artOriginal?.sourceUrl?'Artwork candidate':'Current image');$('artStatus').textContent=artDraftChanged()?status:'';}
function addArtReference(reference){if(!reference)return;if(artReferences.some(item=>item.id===reference.id)){toast('That reference is already attached.');return;}if(artReferences.length>=4){toast('Use up to four reference images.');return;}artReferences.push(reference);renderArtReferences(projects.find(project=>project.id===artProjectId));syncArtReferenceDraft();}
function addFailedArtReference(title,error){const reference={id:crypto.randomUUID(),title:title||'Selected image',error:error||'Could not process this image.'};failedArtReferences.push(reference);renderArtReferences(projects.find(project=>project.id===artProjectId));$('artStatus').textContent=`${reference.title}: ${reference.error}`;}
async function addCurrentArtReference(){const p=projects.find(project=>project.id===artProjectId),requestId=artGenerationRequest;if(!p)return;try{const source=projectArtSource(p),image=source.startsWith('data:image/')?source:await readPhoto(await(await fetch(source)).blob());if(requestId!==artGenerationRequest||!$('artDialog').open)return;addArtReference(artReferenceFromData(image,'Current disk artwork','current-art-'+p.id,'current'));}catch(error){if(requestId===artGenerationRequest)addFailedArtReference('Current disk artwork',error.message||'Could not prepare this reference.');}}
function projectArtReferenceData(){return artReferences.map(({mimeType,data,title})=>({mimeType,data,title}));}
function connectGeminiForArt(){artReturnPending=true;renderGeminiSettings();$('settingsStatus').textContent='';$('settingsDialog').showModal();}
function setArtBusy(busy){$('artLoadingOverlay').hidden=!busy;$('artCropFrame').classList.toggle('is-generating',busy);$('generateProjectArt').disabled=busy;$('artUpload').disabled=busy;$('saveProjectArt').disabled=busy||!artDraftChanged();if(busy)artEditorState='generating';else if(artEditorState==='generating')artEditorState=artDraftChanged()?'candidate-ready':'editing';$('artDialog').dataset.state=artEditorState;}
async function createProjectArt(){const p=projects.find(project=>project.id===artProjectId);if(!p)return;artPrompt=$('artPrompt').value.trim();artContextEnabled=$('artUseProjectContext').checked;$('connectArtGemini').hidden=true;if(!artPrompt){$('artStatus').textContent='Describe the image you want first.';$('artPrompt').focus();return;}if(!googleKey){$('artStatus').textContent='Connect Gemini to generate images.';$('connectArtGemini').hidden=false;return;}const requestId=++artGenerationRequest;setArtBusy(true);$('artStatus').textContent='Creating artwork…';try{const generated=await generateArtwork({key:googleKey,prompt:artPrompt,projectContext:artContextEnabled?projectArtContext(p):'',references:projectArtReferenceData()});const image=await readPhoto(await(await fetch(generated)).blob());if(requestId!==artGenerationRequest||!$('artDialog').open)return;setArtPreview({sourceUrl:image,sourceType:'generated',prompt:artPrompt,useProjectContext:artContextEnabled,references:artReferenceRecords(),generatedAt:new Date().toISOString(),crop:{x:0.5,y:0.5,zoom:1}},'Generated image','Review the crop, then choose “Use image” to save it.');}catch(error){if(requestId!==artGenerationRequest)return;artEditorState='error';$('artDialog').dataset.state=artEditorState;$('artStatus').textContent=error.message||'Could not generate artwork. Check Gemini in Settings and try again.';}finally{if(requestId===artGenerationRequest)setArtBusy(false);}}
function openArtEditor(id){
 const p=projects.find(x=>x.id===id);if(!p)return;
 artProjectId=id;artOriginal=normalizeProjectArt(p.projectArt,p.art);artDraft=makeProjectArt(artOriginal);artPrompt=artDraft.prompt;
 artReferences=artOriginal.references.map(reference=>artReferenceFromData(reference.sourceUrl,reference.title,reference.id,reference.type)).filter(Boolean);
 failedArtReferences=[];artResultReady=false;artEditorState='editing';artContextEnabled=artDraft.useProjectContext;
 $('artDialog').dataset.state=artEditorState;$('artPrompt').value=artPrompt;$('artProjectTitle').value=p.name;$('artDiskPreview').style.setProperty('--disk-color',colorOf(p));
 $('artUseProjectContext').checked=artContextEnabled;$('artProjectContextPreview').textContent=projectArtContext(p)||'No confirmed project context yet.';
 $('artUpload').value='';$('artReferenceUpload').value='';$('connectArtGemini').hidden=true;$('artStatus').textContent='';$('saveProjectArt').disabled=true;$('artCropFrame').dataset.pointer='';
 renderArtReferences(p);setArtPreview(artDraft,'Current image','');$('artDialog').showModal();requestAnimationFrame(()=>syncArtPreview('Current image'));
}
