 $('ideaComposer').insertAdjacentHTML('afterend','<button type="button" id="investigateIdea" class="text-button idea-investigation">Investigate with AI</button>');$('investigateIdea').onclick=()=>runWorkBrief(p,0);
 const raw=$('rawIdea');resizeIdeaComposer(raw);raw.addEventListener('input',()=>{const value=raw.value;idea.rawIdea=value;idea.status=value.trim()?'drafted':'unresolved';idea.updatedAt=new Date().toISOString();p.answers=p.answers||{};p.answers[0]={text:value};$('continueIdea').disabled=!value.trim();setIdeaSaveStatus('Saving…');const chapterState=$('chapters').querySelector('[data-chapter="0"]');if(chapterState){chapterState.classList.toggle('drafted',!!value.trim());const chapterLabel=chapterState.querySelector('small');if(chapterLabel)chapterLabel.textContent=value.trim()?'Draft':'Next';}resizeIdeaComposer(raw);clearTimeout(ideaSaveTimer);ideaSaveTimer=setTimeout(()=>{persist();setIdeaSaveStatus(saveError?'Not saved':'Saved');},500);});
 $('ideaComposer').onsubmit=e=>{e.preventDefault();clearTimeout(ideaSaveTimer);idea.rawIdea=raw.value;idea.status=raw.value.trim()?'drafted':'unresolved';p.answers[0]={text:raw.value};persist();if(!googleKey){ideaNotice='Connect Gemini to shape a Working Idea. Your notes are saved.';renderProject();return;}generateWorkingIdeaFor(p,idea.clarificationResponse||'');};
